import {initialRequests,mergeCuratedRequests,amountOf,safeUrl,contribute,deliver} from './model.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],key='backnext-demo-v1';
let state=initialRequests(),filter='open',view='board',timer;
try{const stored=JSON.parse(localStorage.getItem(key));if(Array.isArray(stored)&&stored.every(r=>typeof r.id==='string'&&typeof r.title==='string'&&typeof r.description==='string'&&typeof r.category==='string'&&Number.isSafeInteger(r.goal)&&r.goal>0&&Number.isSafeInteger(r.total)&&r.total>=0&&Array.isArray(r.contributions)&&r.contributions.every(c=>typeof c.id==='string'&&Number.isSafeInteger(c.amount)&&typeof c.at==='string')&&(!r.delivered||safeUrl(r.delivered))))state=stored;}catch{}
state=mergeCuratedRequests(state);
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
function animate(element,frames,options={}){if(!reducedMotion.matches && element?.animate)element.animate(frames,{duration:240,easing:'cubic-bezier(.2,.7,.2,1)',...options});}
function scrollToSection(element){element.setAttribute('tabindex','-1');element.focus({preventScroll:true});element.scrollIntoView({behavior:reducedMotion.matches?'instant':'smooth',block:'start'});}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('en-US').format(n);
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',5000);}
function save(next){try{localStorage.setItem(key,JSON.stringify(next));}catch{throw new Error('Your browser cannot save this change. Free some storage or enable local storage and try again.');}state=next;render();}
function show(content){$('#modal-content').innerHTML=content;$('#modal').showModal();animate($('#modal-content'),[{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}]);}
function close(){$('#modal').close();}
function render(){const open=state.filter(r=>!r.delivered),done=state.filter(r=>r.delivered);$('#total-backed').textContent=fmt(state.reduce((s,r)=>s+r.total,0));$('#total-delivered').textContent=done.length;$('#open-count').textContent=open.length;$('#done-count').textContent=done.length;const visible=filter==='open'?open:done;
$('#cards').innerHTML=visible.length?visible.map((r,i)=>`<article class="request-card" style="--card-delay:${Math.min(i,5)*45}ms"><div class="card-art ${['purple','peach'].includes(r.color)?r.color:''}"><span class="card-number">REQUEST / ${String(i+1).padStart(2,'0')}</span><div class="art-window"><small>MAKE SOMETHING GOOD</small><strong>${esc(r.art||'↗ + ✦')}</strong></div></div><div class="card-body"><div class="card-label"><span>${esc(r.category)}</span><b>${r.delivered?'✓ DELIVERED':'↗ OPEN FOR BACKING'}</b></div><h3>${esc(r.title)}</h3><p class="card-description">${esc(r.description)}</p>${r.outcome?`<div class="deliverable"><span>THE FINISHED RESULT</span><strong>${esc(r.outcome)}</strong><small>${esc(r.audience||'')}</small></div>`:''}<div class="progress-label"><strong>${fmt(r.total)} <small>$wif</small></strong><span>of ${fmt(r.goal)} goal · demo</span></div><div class="progress" role="progressbar" aria-label="Demo backing for ${esc(r.title)}" aria-valuenow="${Math.min(100,Math.round(r.total/r.goal*100))}" aria-valuemin="0" aria-valuemax="100"><div style="width:${Math.min(100,r.total/r.goal*100)}%"></div></div><div class="backer-count">${r.contributions.length} demo contribution${r.contributions.length===1?'':'s'} · <button class="text-button" data-receipts="${esc(r.id)}">View receipts</button></div>${r.delivered?`<a class="back-button delivered-link" href="${esc(safeUrl(r.delivered))}" target="_blank" rel="noopener noreferrer">See the finished work <span>↗</span></a>`:`<button class="back-button" data-back="${esc(r.id)}">Back this request <span>↗</span></button>`}</div></article>`).join(''):`<div class="empty"><h3>${filter==='open'?'Time for the next idea.':'The next chapter is still being made.'}</h3><p>${filter==='open'?'Open the creator studio to publish a new request.':'Try backing a request, then attach a finished-work link in the creator studio.'}</p><button class="outline" data-studio>Open creator studio ↗</button></div>`;
$('#studio-list').innerHTML=state.map(r=>`<div class="studio-item"><div><strong>${esc(r.title)}</strong><small>${fmt(r.total)} demo $wif · ${r.delivered?'Delivered':'Open'}</small></div>${r.delivered?'<span class="sample">✓ DELIVERED</span>':`<button class="outline" data-deliver="${esc(r.id)}">Add result ↗</button>`}</div>`).join('');
$$('[data-back]').forEach(b=>b.onclick=()=>back(b.dataset.back));$$('[data-deliver]').forEach(b=>b.onclick=()=>finish(b.dataset.deliver));$$('[data-receipts]').forEach(b=>b.onclick=()=>receipts(b.dataset.receipts));$$('[data-studio]').forEach(b=>b.onclick=()=>setView('studio'));
}
function setView(next){view=next;$('#board-view').hidden=view!=='board';$('#studio-view').hidden=view!=='studio';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const section=$(view==='studio'?'#studio-view':'#board-view');animate(section,[{opacity:0,transform:'translateY(9px)'},{opacity:1,transform:'translateY(0)'}]);if(view==='studio')scrollToSection(section);}
function back(id){const r=state.find(x=>x.id===id);show(`<p class="eyebrow">BACK AN IDEA · DEMO</p><h2 class="modal-title">${esc(r.title)}</h2><p class="muted">Help make this creator’s next piece of work possible.</p><form id="back-form"><label>Your support ($wif)<input name="amount" id="amount" type="number" min="1" max="1000000000" step="1" value="100" required></label><div class="presets"><button type="button" data-amount="50">50 $wif</button><button type="button" data-amount="100">100 $wif</button><button type="button" data-amount="250">250 $wif</button></div><div class="modal-summary"><strong>No wallet or funds needed.</strong><br>This is a simulated contribution. This board does not send live payments. Backing is support, not a purchase, investment, or guarantee of delivery.</div><p class="error" id="form-error" role="alert"></p><button class="primary full" type="submit">Confirm demo backing <span>↗</span></button></form>`);$$('[data-amount]').forEach(b=>b.onclick=()=>$('#amount').value=b.dataset.amount);$('#back-form').onsubmit=e=>{e.preventDefault();try{const amount=amountOf($('#amount').value),receipt='DEMO-'+crypto.randomUUID().slice(0,8).toUpperCase();save(state.map(x=>x.id===id?contribute(x,amount,receipt):x));show(`<div class="success-mark" aria-hidden="true">✓</div><p class="eyebrow">SIMULATION COMPLETE</p><h2 class="modal-title">You backed what’s next.</h2><p class="muted">${fmt(amount)} demo $wif added to “${esc(r.title)}”.</p><div class="modal-summary"><strong>Demo receipt</strong><br>${esc(receipt)}<br>Saved in this browser. No blockchain transaction was sent.</div><button class="primary full" id="back-done">Back to the board ↗</button>`);$('#back-done').onclick=close;}catch(err){$('#form-error').textContent=err.message;}};}
function finish(id){const r=state.find(x=>x.id===id);show(`<p class="eyebrow">CLOSE THE LOOP · DEMO</p><h2 class="modal-title">Show what you made.</h2><p class="muted">${esc(r.title)}</p><form id="finish-form"><label>Link to the finished work<input id="result-url" required type="url" placeholder="https://youtube.com/watch?v=..."></label><p class="fine">This moves the request to Delivered and closes backing. Use a real link to your work; publishing here is a local simulation.</p><p class="error" id="form-error" role="alert"></p><button class="primary full">Mark delivered ↗</button></form>`);$('#finish-form').onsubmit=e=>{e.preventDefault();try{save(state.map(x=>x.id===id?deliver(x,$('#result-url').value):x));close();toast('Result attached. Your request is now in Delivered.');}catch(err){$('#form-error').textContent=err.message;}};}
function receipts(id){const r=state.find(x=>x.id===id);show(`<p class="eyebrow">DEMO RECEIPTS</p><h2 class="modal-title">Every little backing.</h2><p class="muted">${esc(r.title)}</p><ul class="history">${r.contributions.length?r.contributions.map(c=>`<li><strong>${fmt(c.amount)} demo $wif</strong><small>${esc(c.id)} · ${esc(new Date(c.at).toLocaleString())}</small></li>`).join(''):'<li>No contributions yet. Be the first to try backing this request.</li>'}</ul><p class="fine">These are local demo records, not blockchain receipts.</p>`);}
function how(){show(`<p class="eyebrow">THE BACKNEXT LOOP</p><h2 class="modal-title">A shared say in what comes next.</h2><div class="modal-summary"><strong>01 — Pick an idea.</strong><br>A creator shares work they’d like to make.<br><br><strong>02 — Give it a little backing.</strong><br>Fans support the requests they want to see with $wif.<br><br><strong>03 — Come back for the result.</strong><br>The creator attaches the finished work, then opens another request.</div><p class="fine">This version lets you try every step with simulated backing. It does not take payments. In the intended live product, support goes directly to the creator and doesn’t promise a return or guaranteed delivery.</p>`);}
$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render();});$('#close').onclick=close;$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}};if($('#how'))$('#how').onclick=how;$('#how-bottom').onclick=how;
$('a[href="#requests"]').onclick=e=>{e.preventDefault();setView('board');requestAnimationFrame(()=>scrollToSection($('#requests')));};
$('#create-form').onsubmit=e=>{e.preventDefault();try{const data=new FormData(e.target),title=data.get('title').trim(),description=data.get('description').trim();if(!title||!description)throw new Error('Add a title and a description.');save([...state,{id:crypto.randomUUID(),title,description,category:data.get('category'),goal:amountOf(data.get('goal')),total:0,contributions:[],delivered:null,art:'↗ + ✦',color:'purple'}]);e.target.reset();toast('Demo request published. Find it on the board.');}catch(err){toast(err.message);}};
$('#reset').onclick=()=>{show(`<p class="eyebrow">START FRESH</p><h2 class="modal-title">Reset this demo?</h2><p class="muted">This removes requests, backing, and delivered links saved in this browser and restores the six curated sample ideas.</p><button class="primary full" id="confirm-reset">Reset local demo ↻</button>`);$('#confirm-reset').onclick=()=>{try{save(initialRequests());close();toast('Demo reset. Ready for a new round.');}catch(err){toast(err.message);}};};
$('#build-status').onclick=()=>show(`<p class="eyebrow">BACKNEXT · DEMO EDITION</p><h2 class="modal-title">Backed. Built. Delivered.</h2><div class="modal-summary"><strong>Ready to explore</strong><br>Six curated ideas, simulated backing and receipts, your own requests, and links to finished work.<br><br><strong>Demo boundaries</strong><br>No wallet connection, token approvals, swaps, or real payments. Everything you create stays in this browser. Other visitors see their own demo.</div><p class="fine">A separate live pilot accepts direct $wif support for the portfolio request. <a href="support/">Open the live request ↗</a> This demo board still uses simulated balances.</p>`);
render();

// Delegated feedback also covers controls created inside dialogs and request cards.
document.addEventListener('click',event=>{
 const control=event.target.closest('button, a.primary, a.back-button');
 if(!control || control.disabled || reducedMotion.matches)return;
 animate(control,[{transform:'scale(1)'},{transform:'scale(.96)',offset:.35},{transform:'scale(1)'}],{duration:220});
});
